{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

export function openProjects(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec(`
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
  `);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
  }
  const list = database.prepare(`
    SELECT projects.id, projects.name, projects.archived,
      COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
    FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
    WHERE projects.archived = ? GROUP BY projects.id ORDER BY projects.id
  `);
  const find = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const archiveUpdate = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const renameUpdate = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
  const taskList = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
  const taskInsert = database.prepare('INSERT INTO tasks (project_id, title) SELECT id, ? FROM projects WHERE id = ? AND archived = 0');
  const taskUpdate = database.prepare(`UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?
    AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)`);

  return {
    list: (archived = false) => list.all(archived ? 1 : 0),
    find: (id) => find.get(id),
    setArchived: (id, archived) => archiveUpdate.run(archived ? 1 : 0, id).changes === 1,
    create(name) {
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) return null;
      const result = insert.run(trimmedName);
      return find.get(result.lastInsertRowid);
    },
    rename(id, name) {
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) return false;
      return renameUpdate.run(trimmedName, id).changes === 1;
    },
    listTasks: (projectId) => taskList.all(projectId),
    createTask(projectId, title) {
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) return null;
      const result = taskInsert.run(trimmedTitle, projectId);
      return result.changes === 1 ? Number(result.lastInsertRowid) : null;
    },
    setTaskCompleted(projectId, taskId, completed) {
      return taskUpdate.run(completed ? 1 : 0, projectId, taskId).changes === 1;
    },
    close: () => database.close(),
  };
}
import { createServer } from 'node:http';
import { openProjects } from './projects.js';

const projects = openProjects(process.env.DB_PATH || 'data/workboard.sqlite');
const port = Number(process.env.PORT || 8080);

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <style>
    :root { font-family: system-ui, sans-serif; color: #172b40; background: #f3f6fa; }
    body { margin: 0; }
    main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border-radius: 16px; box-shadow: 0 8px 32px #172b4010; }
    h1 { margin-top: 0; overflow-wrap: anywhere; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    .create { display: flex; gap: 12px; }
    input { min-width: 0; flex: 1; border: 1px solid #8192a5; border-radius: 6px; padding: 12px; font: inherit; }
    button { border: 0; border-radius: 6px; padding: 12px 18px; background: #205bc4; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #17489e; }
    button:disabled { background: #8192a5; cursor: default; }
    :focus-visible { outline: 3px solid #dc8b00; outline-offset: 3px; }
    [role="alert"] { color: #a02020; margin: 16px 0; }
    .projects { margin-top: 28px; }
    .project { display: flex; align-items: center; justify-content: space-between; gap: 20px; border-top: 1px solid #dce3ec; padding: 18px 0; }
    .project span { overflow-wrap: anywhere; min-width: 0; }
    .project form { flex-shrink: 0; }
    .task { display: flex; align-items: center; gap: 12px; border-top: 1px solid #dce3ec; padding: 18px 0; overflow-wrap: anywhere; }
    .task input { flex: none; width: 20px; height: 20px; }
    .task label { margin: 0; font-weight: 400; min-width: 0; }
    .task-controls { margin-top: 28px; }
    select { padding: 10px; font: inherit; border: 1px solid #8192a5; border-radius: 6px; }
    .empty { color: #536578; }
    @media (max-width: 600px) { main { margin: 16px; padding: 24px; } .create { flex-direction: column; } .project { flex-wrap: wrap; } .project > div { width: 100%; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

const projectFilters = ['Active', 'Archived'];

function normalizeProjectFilter(value) {
  return projectFilters.includes(value) ? value : 'Active';
}

function projectList(error = '', filter = 'Active') {
  const rows = projects.list(filter === 'Archived').map((project) => `
    <div class="project" data-testid="project-row">
      <div><span>${escapeHtml(project.name)}</span>
        <p data-testid="project-summary">${project.completed_count}/${project.total_count} completed</p></div>
      <form action="/projects/${project.id}" method="get"><button type="submit">Open project</button></form>
      <form action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}" method="post">
        <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
      </form>
    </div>`).join('');
  return page('Projects', `
    <h1>Workboard</h1>
    <form action="/projects" method="post">
      <label for="project-name">Project name</label>
      <div class="create"><input id="project-name" name="name" type="text"><button type="submit">Create project</button></div>
    </form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="task-controls" action="/" method="get">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${projectFilters.map((option) => `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <div class="projects">${rows || '<p class="empty">No projects yet.</p>'}</div>`);
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  response.end(html);
}

const taskFilters = ['All', 'Open', 'Completed'];

function normalizeFilter(value) {
  return taskFilters.includes(value) ? value : 'All';
}

function projectPage(project, filter = 'All', error = '') {
  const rows = projects.listTasks(project.id)
    .filter((task) => filter === 'All' || Boolean(task.completed) === (filter === 'Completed'))
    .map((task) => `<form class="task" data-testid="task-row" action="/projects/${project.id}/tasks/${task.id}" method="post">
      <input type="hidden" name="filter" value="${filter}">
      <input id="task-${task.id}" type="checkbox" name="completed" value="1" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''} ${project.archived ? 'disabled' : ''} onchange="this.form.requestSubmit()">
      <label for="task-${task.id}">${escapeHtml(task.title)}</label>
    </form>`).join('');
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form action="/" method="get"><button type="submit">Projects</button></form>
    <form class="task-controls" action="/projects/${project.id}/rename" method="post">
      <input type="hidden" name="filter" value="${filter}">
      <label for="new-project-name">New project name</label>
      <div class="create"><input id="new-project-name" name="name" type="text"${project.archived ? ' disabled' : ''}><button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button></div>
    </form>
    <form class="task-controls" action="/projects/${project.id}/tasks" method="post">
      <input type="hidden" name="filter" value="${filter}">
      <label for="task-title">Task title</label>
      <div class="create"><input id="task-title" name="title" type="text"><button type="submit"${project.archived ? ' disabled' : ''}>Create task</button></div>
    </form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="task-controls" action="/projects/${project.id}" method="get">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${taskFilters.map((option) => `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <div class="tasks">${rows || '<p class="empty">No matching tasks.</p>'}</div>`);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 16384) return null;
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

const server = createServer(async (request, response) => {
  try {
    const { pathname, searchParams } = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (request.method === 'GET' && pathname === '/') {
      sendHtml(response, 200, projectList('', normalizeProjectFilter(searchParams.get('filter'))));
      return;
    }
    if (request.method === 'POST' && pathname === '/projects') {
      const body = await readForm(request);
      if (!body) {
        sendHtml(response, 413, page('Request too large', '<h1>Request too large</h1>'));
        return;
      }
      const project = projects.create(body.get('name'));
      if (!project) {
        sendHtml(response, 422, projectList('Project name is required'));
        return;
      }
      redirect(response, '/');
      return;
    }
    const match = /^\/projects\/([1-9]\d*)$/.exec(pathname);
    if (request.method === 'GET' && match) {
      const id = Number(match[1]);
      const project = Number.isSafeInteger(id) ? projects.find(id) : null;
      if (project) {
        sendHtml(response, 200, projectPage(project, normalizeFilter(searchParams.get('filter'))));
        return;
      }
    }
    const renameMatch = /^\/projects\/([1-9]\d*)\/rename$/.exec(pathname);
    if (request.method === 'POST' && renameMatch) {
      const id = Number(renameMatch[1]);
      const project = Number.isSafeInteger(id) ? projects.find(id) : null;
      if (project) {
        const body = await readForm(request);
        if (!body) {
          sendHtml(response, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
        const filter = normalizeFilter(body.get('filter'));
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filter, 'Archived project is read-only'));
          return;
        }
        if (!projects.rename(id, body.get('name'))) {
          sendHtml(response, 422, projectPage(project, filter, 'Project name is required'));
          return;
        }
        redirect(response, `/projects/${id}?filter=${filter}`);
        return;
      }
    }
    const archiveMatch = /^\/projects\/([1-9]\d*)\/(archive|restore)$/.exec(pathname);
    if (request.method === 'POST' && archiveMatch) {
      const id = Number(archiveMatch[1]);
      if (Number.isSafeInteger(id) && projects.setArchived(id, archiveMatch[2] === 'archive')) {
        redirect(response, archiveMatch[2] === 'archive' ? '/' : '/?filter=Archived');
        return;
      }
    }
    const taskMatch = /^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/.exec(pathname);
    if (request.method === 'POST' && taskMatch) {
      const projectId = Number(taskMatch[1]);
      const taskId = taskMatch[2] ? Number(taskMatch[2]) : null;
      const project = Number.isSafeInteger(projectId) ? projects.find(projectId) : null;
      if (project && (taskId === null || Number.isSafeInteger(taskId))) {
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, normalizeFilter(searchParams.get('filter')), 'Archived project is read-only'));
          return;
        }
        const body = await readForm(request);
        if (!body) {
          sendHtml(response, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
        const filter = normalizeFilter(body.get('filter'));
        if (taskId === null) {
          if (!projects.createTask(projectId, body.get('title'))) {
            sendHtml(response, 422, projectPage(project, filter, 'Task title is required'));
            return;
          }
        } else if (!projects.setTaskCompleted(projectId, taskId, body.get('completed') === '1')) {
          sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
        redirect(response, `/projects/${projectId}?filter=${filter}`);
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Page not found</h1><form action="/" method="get"><button>Projects</button></form>'));
  } catch (error) {
    console.error(error);
    if (!response.headersSent) sendHtml(response, 500, page('Server error', '<h1>Unable to complete your request</h1>'));
    else response.end();
  }
});

server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on port ${server.address().port}`));

function shutdown() {
  server.close(() => {
    projects.close();
    process.exit(0);
  });
}
process.once('SIGTERM', shutdown);
process.once('SIGINT', shutdown);
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import test from 'node:test';
import { openProjects } from '../projects.js';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', (chunk) => { errors += chunk; });
  const baseUrl = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${errors}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timeout); reject(error); });
    child.once('exit', (code) => {
      clearTimeout(timeout);
      reject(new Error(`Server exited with ${code}: ${errors}`));
    });
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = /listening on port (\d+)/.exec(output);
      if (match) {
        clearTimeout(timeout);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    baseUrl,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('rename storage rejects invalid and archived edits without changing project identity', () => {
  const projects = openProjects(':memory:');
  try {
    const project = projects.create('Original');
    const taskId = projects.createTask(project.id, 'Task');
    projects.setTaskCompleted(project.id, taskId, true);
    for (const name of [null, undefined, '', ' \t\n ', 42]) {
      assert.equal(projects.rename(project.id, name), false);
      assert.equal(projects.find(project.id).name, 'Original');
    }
    assert.equal(projects.rename(project.id, '  Renamed  '), true);
    assert.deepEqual({ ...projects.find(project.id) }, { id: project.id, name: 'Renamed', archived: 0 });
    assert.deepEqual(projects.listTasks(project.id).map((task) => ({ ...task })), [{ id: taskId, title: 'Task', completed: 1 }]);
    projects.setArchived(project.id, true);
    assert.equal(projects.rename(project.id, 'Blocked'), false);
    assert.equal(projects.find(project.id).name, 'Renamed');
    projects.setArchived(project.id, false);
    assert.equal(projects.rename(project.id, 'Restored'), true);
    assert.equal(projects.rename(99999, 'Missing'), false);
  } finally {
    projects.close();
  }
});

test('renaming preserves order, tasks, summaries, filters, and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-rename-'));
  let server;
  try {
    const databasePath = join(directory, 'workboard.sqlite');
    server = await startServer(databasePath);
    const html = async (path) => (await fetch(`${server.baseUrl}${path}`)).text();
    const post = (path, values = {}) => fetch(`${server.baseUrl}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    await post('/projects', { name: 'Original' });
    await post('/projects', { name: 'Second project' });
    await post('/projects/1/tasks', { title: 'Finished task' });
    await post('/projects/1/tasks', { title: 'Open task' });
    await post('/projects/1/tasks/1', { completed: '1' });
    const initial = await html('/projects/1');
    assert.match(initial, /<label for="new-project-name">New project name<\/label>/);
    assert.match(initial, /id="new-project-name"[^>]*type="text"/);
    assert.match(initial, /<button type="submit">Rename project<\/button>/);

    for (const values of [{}, { name: '' }, { name: ' \t\n ', filter: 'Completed' }]) {
      const response = await post('/projects/1/rename', values);
      assert.equal(response.status, 422);
      const content = await response.text();
      assert.match(content, /role="alert">Project name is required/);
      assert.match(content, /<h1>Original<\/h1>/);
      if (values.filter) assert.match(content, /<option selected>Completed<\/option>/);
      assert.equal(await html('/projects/1'), initial);
    }
    const renamed = await post('/projects/1/rename', { name: '  Renamed <&" café  ', filter: 'Open' });
    assert.equal(renamed.status, 303);
    assert.equal(renamed.headers.get('location'), '/projects/1?filter=Open');
    const savedPage = await html('/projects/1');
    assert.match(savedPage, /<h1>Renamed &lt;&amp;&quot; café<\/h1>/);
    assert.match(savedPage, /aria-label="Complete Finished task" checked/);
    assert.match(savedPage, /aria-label="Complete Open task"  /);
    assert.equal((savedPage.match(/data-testid="task-row"/g) || []).length, 2);
    const savedList = await html('/');
    assert.match(savedList, /<span>Renamed &lt;&amp;&quot; café<\/span>/);
    assert.match(savedList, /data-testid="project-summary">1\/2 completed/);
    assert.ok(savedList.indexOf('Renamed &lt;') < savedList.indexOf('Second project'));
    assert.match(savedList, /action="\/projects\/1"/);
    assert.equal((await post('/projects/99999/rename', { name: 'Missing' })).status, 404);
    assert.equal((await post('/projects/999999999999999999999/rename', { name: 'Missing' })).status, 404);
    const oversized = await post('/projects/1/rename', { name: 'a'.repeat(17000) });
    assert.equal(oversized.status, 413);
    assert.equal(await html('/projects/1'), savedPage);

    await server.stop();
    server = undefined;
    server = await startServer(databasePath);
    assert.equal(await html('/projects/1'), savedPage);
    assert.equal(await html('/'), savedList);
    await post('/projects/1/archive');
    const archivedPage = await html('/projects/1');
    assert.match(archivedPage, /id="new-project-name"[^>]* disabled/);
    assert.match(archivedPage, /<button type="submit" disabled>Rename project<\/button>/);
    const blocked = await post('/projects/1/rename', { name: 'Blocked', filter: 'Open' });
    assert.equal(blocked.status, 403);
    assert.match(await blocked.text(), /<option selected>Open<\/option>/);
    assert.equal(await html('/projects/1'), archivedPage);
    assert.match(await html('/?filter=Archived'), /<span>Renamed &lt;&amp;&quot; café<\/span>/);

    await server.stop();
    server = undefined;
    server = await startServer(databasePath);
    assert.equal(await html('/projects/1'), archivedPage);
    await post('/projects/1/restore');
    assert.equal(await html('/projects/1'), savedPage);
    assert.equal((await post('/projects/1/rename', { name: '  Restored name  ' })).status, 303);
    const finalPage = await html('/projects/1');
    const finalList = await html('/');
    assert.match(finalPage, /<h1>Restored name<\/h1>/);
    assert.match(finalPage, /aria-label="Complete Finished task" checked/);
    assert.match(finalList, /data-testid="project-summary">1\/2 completed/);
    assert.ok(finalList.indexOf('Restored name') < finalList.indexOf('Second project'));
    await server.stop();
    server = undefined;
    server = await startServer(databasePath);
    assert.equal(await html('/projects/1'), finalPage);
    assert.equal(await html('/'), finalList);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('project validation, ordering, navigation, escaping, and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  let server;
  try {
    const databasePath = join(directory, 'nested', 'projects.sqlite');
    server = await startServer(databasePath);
    const get = (path) => fetch(`${server.baseUrl}${path}`);
    const create = (name) => fetch(`${server.baseUrl}/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ name }),
      redirect: 'manual',
    });
    const health = await get('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    const initial = await (await get('/')).text();
    assert.match(initial, /<h1>Workboard<\/h1>/);
    assert.match(initial, /<label for="project-name">Project name<\/label>/);
    assert.match(initial, />Create project<\/button>/);
    assert.doesNotMatch(initial, /data-testid="project-row"/);

    for (const name of ['', ' \t\n ']) {
      const invalid = await create(name);
      assert.equal(invalid.status, 422);
      const html = await invalid.text();
      assert.match(html, /role="alert">Project name is required/);
      assert.doesNotMatch(html, /data-testid="project-row"/);
    }
    const created = await create('  First project  ');
    assert.equal(created.status, 303);
    assert.equal(created.headers.get('location'), '/');
    assert.equal((await create('<script> & café')).status, 303);
    const listing = await (await get('/')).text();
    assert.equal((listing.match(/data-testid="project-row"/g) || []).length, 2);
    assert.match(listing, /<span>First project<\/span>/);
    assert.match(listing, /&lt;script&gt; &amp; café/);
    assert.ok(listing.indexOf('First project') < listing.indexOf('&lt;script&gt;'));
    const paths = [...listing.matchAll(/action="(\/projects\/\d+)"/g)].map((match) => match[1]);
